import json
import logging
import re
from flask import Flask, request, jsonify
from datetime import datetime

app = Flask(__name__)

# Configure logging with structured format for ELK stack ingestion
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s [%(levelname)s] device=%(device_id)s action=%(action)s msg=%(message)s',
    handlers=[logging.FileHandler('/var/log/iot-gateway/messages.log'), logging.StreamHandler()]
)

class DeviceMessageHandler:
    """Handles incoming MQTT-bridged messages from IoT devices via HTTP gateway"""

    VALID_ACTIONS = ['telemetry', 'heartbeat', 'alert', 'config_ack', 'firmware_status']

    def __init__(self):
        self.message_count = 0
        self.device_registry = {}

    def validate_device_id(self, device_id):
        """Basic device ID format validation"""
        if not device_id or len(device_id) > 64:
            return False
        # Allow alphanumeric, hyphens, underscores
        return bool(re.match(r'^[a-zA-Z0-9_-]+$', device_id))

    def process_message(self, payload):
        """Process incoming device message and log for audit trail"""
        device_id = payload.get('device_id', 'unknown')
        action = payload.get('action', 'unknown')
        message_body = payload.get('message', '')
        timestamp = payload.get('timestamp', datetime.utcnow().isoformat())

        # Validate device_id format
        if not self.validate_device_id(device_id):
            logging.warning(
                'Invalid device ID received',
                extra={'device_id': 'INVALID', 'action': 'rejected'}
            )
            return {'status': 'error', 'reason': 'invalid_device_id'}, 400

        # Validate action
        if action not in self.VALID_ACTIONS:
            logging.warning(
                f'Unknown action: {action}',
                extra={'device_id': device_id, 'action': 'unknown_action'}
            )
            return {'status': 'error', 'reason': 'invalid_action'}, 400

        # Log the message for audit - message_body is NOT sanitized for log injection
        # The message field from the device payload is directly interpolated
        log_entry = f'Processed {action} from device at {timestamp}: {message_body}'
        logging.info(
            log_entry,
            extra={'device_id': device_id, 'action': action}
        )

        self.message_count += 1
        self.device_registry[device_id] = {
            'last_seen': timestamp,
            'last_action': action
        }

        return {'status': 'ok', 'message_id': self.message_count}, 200

handler = DeviceMessageHandler()

@app.route('/api/v1/device/message', methods=['POST'])
def receive_message():
    """Endpoint for IoT device messages forwarded from MQTT bridge"""
    if not request.is_json:
        return jsonify({'error': 'Content-Type must be application/json'}), 415

    payload = request.get_json(silent=True)
    if not payload:
        return jsonify({'error': 'Invalid JSON payload'}), 400

    result, status_code = handler.process_message(payload)
    return jsonify(result), status_code

@app.route('/api/v1/device/status', methods=['GET'])
def device_status():
    """Returns registered device status - internal use only"""
    device_id = request.args.get('id', '')
    if device_id in handler.device_registry:
        return jsonify(handler.device_registry[device_id]), 200
    return jsonify({'error': 'device not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'messages_processed': handler.message_count}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
